def newman_prime(n):
    from math import sqrt, floor

    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, floor(sqrt(num)) + 1, 2):
            if num % i == 0:
                return False
        return True

