    if n < 3:
        return nsr_primes[n - 1]
    i = 3
    while len(nsr_primes) < n:
        next_prime = nsr_primes[i - 2] ** 2 - nsr_primes[i - 1] ** 2
        if is_prime(next_prime):
            nsr_primes.append(next_prime)
        i += 1
    return nsr_primes[n - 1]
